import { motion } from "framer-motion";

export default function Hero() {
  return (
    <section
      id="hero"
      className="min-h-screen flex items-center justify-center text-center px-6 pt-24"
    >
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.9 }}
        className="max-w-4xl"
      >
        <h1 className="text-5xl md:text-6xl font-bold leading-tight">
          Training Built on{" "}
          <span className="text-red-600">Structure</span>, Not Shortcuts
        </h1>

        <p className="mt-6 text-lg text-gray-300">
          Structured training, consistent coaching, and disciplined workout
          environments designed for long-term fitness.
        </p>

        <div className="mt-10 flex justify-center gap-4 flex-wrap">
          {/* MEMBERSHIP BUTTON */}
          <a href="#membership">
            <button className="px-6 py-3 bg-red-700 hover:bg-red-600 transition rounded red-glow">
              View Membership Plans
            </button>
          </a>

          {/* PROGRAMS BUTTON */}
          <a href="#programs">
            <button className="px-6 py-3 border border-red-700 hover:bg-red-700/20 transition rounded">
              Explore Programs
            </button>
          </a>
        </div>
      </motion.div>
    </section>
  );
}
